package com.farika.soundflow;
import android.content.*;import android.net.*;import android.database.sqlite.*;import org.json.*;import java.util.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.shadows.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=android.app.Application.class)
public class QueueStartupTest {
 Context c;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();c.getSharedPreferences("profile",0).edit().putString("id","123").commit();}
 List<Library.Track> tracks()throws Exception{List<Library.Track> a=LibraryPagerTest.page(0,165,false).tracks;for(int i=0;i<a.size();i++)a.get(i).remote=new JSONObject().put("id",""+(1000+i));return a;}
 void cached()throws Exception{new PlaylistCache(c).put("likes","Любимое","favorites",tracks(),false,"123");}
 void plan(boolean auto){try(SyncDb db=new SyncDb(c)){db.ensure("123","likes","Любимое","favorites");db.auto("123","likes",auto);}}
 JSONObject plan(){try(SyncDb db=new SyncDb(c)){return db.plans("123",false).get(0);}}
 NetworkCapabilities caps(int transport){NetworkCapabilities n=new NetworkCapabilities();ShadowNetworkCapabilities s=Shadows.shadowOf(n);s.clearCapabilities();s.addTransportType(transport);s.addCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET);return n;}
 NetworkInfo info(int type,boolean connected){return ShadowNetworkInfo.newInstance(connected?NetworkInfo.DetailedState.CONNECTED:NetworkInfo.DetailedState.DISCONNECTED,type,0,true,connected);}
 @Test public void enablingUsesAll165CachedSongs()throws Exception{cached();assertTrue(AutoDownloads.toggle(c,"123","likes","Любимое","favorites"));try(SyncDb db=new SyncDb(c)){assertEquals(165,db.totals("123","likes")[0]);assertEquals(165,db.totals("123","likes")[3]);}assertTrue(plan().optBoolean("listed"));assertTrue(plan().optBoolean("active"));}
 @Test public void openingOldEmptyAutoPlanRepairsFromCache()throws Exception{plan(true);cached();AutoDownloads.prepare(c);try(SyncDb db=new SyncDb(c)){assertEquals(165,db.tracks("123","likes").size());}assertTrue(plan().optBoolean("listed"));}
 @Test public void unknownAutoPlanGetsRetry(){plan(true);try(SyncDb db=new SyncDb(c)){assertFalse(db.plans("123",false).get(0).optBoolean("listed"));assertTrue(db.nextAutomaticRetry("123")>0);}}
 @Test public void trulyEmptyListIsKnownAndDoesNotRapidRetry()throws Exception{plan(true);try(SyncDb db=new SyncDb(c)){db.snapshot("123","likes",Collections.emptyList());assertTrue(db.plans("123",false).get(0).optBoolean("listed"));assertEquals(0,db.nextAutomaticRetry("123"));}}
 @Test public void cachedListDoesNotOverwriteExistingProgress()throws Exception{plan(true);cached();try(SyncDb db=new SyncDb(c)){db.snapshot("123","likes",tracks());String id=tracks().get(0).id();db.state("123","likes",id,"READY","");AutoDownloads.seedCached(c,"123","likes",db);assertEquals(1,db.totals("123","likes")[1]);}}
 @Test public void cannotSeedOtherAccount()throws Exception{plan(true);cached();try(SyncDb db=new SyncDb(c)){AutoDownloads.seedCached(c,"999","likes",db);assertEquals(0,db.totals("123","likes")[0]);}}
 @Test public void wifiPermitted(){assertTrue(AutoDownloads.allowed(caps(NetworkCapabilities.TRANSPORT_WIFI),info(ConnectivityManager.TYPE_WIFI,true),true));}
 @Test public void cellularRejectedEvenIfUnmetered(){NetworkCapabilities n=caps(NetworkCapabilities.TRANSPORT_CELLULAR);Shadows.shadowOf(n).addCapability(NetworkCapabilities.NET_CAPABILITY_NOT_METERED);assertFalse(AutoDownloads.allowed(n,info(ConnectivityManager.TYPE_MOBILE,true),true));}
 @Test public void vpnWithConfirmedWifiPermitted(){assertTrue(AutoDownloads.allowed(caps(NetworkCapabilities.TRANSPORT_VPN),info(ConnectivityManager.TYPE_WIFI,true),true));}
 @Test public void vpnWithCellularRejected(){assertFalse(AutoDownloads.allowed(caps(NetworkCapabilities.TRANSPORT_VPN),info(ConnectivityManager.TYPE_MOBILE,true),true));}
 @Test public void vpnWithoutUnderlyingInfoRejected(){assertFalse(AutoDownloads.allowed(caps(NetworkCapabilities.TRANSPORT_VPN),null,true));assertFalse(AutoDownloads.allowed(caps(NetworkCapabilities.TRANSPORT_VPN),info(ConnectivityManager.TYPE_WIFI,false),true));}
 @Test public void wifiSettingOffAllowsCellular(){assertTrue(AutoDownloads.allowed(caps(NetworkCapabilities.TRANSPORT_CELLULAR),null,false));}
 @Test public void migrationKeepsOldRowsAndMarksKnown()throws Exception{c.deleteDatabase("downloads.db");SQLiteDatabase d=c.openOrCreateDatabase("downloads.db",0,null);d.execSQL("CREATE TABLE plans(owner TEXT,id TEXT,title TEXT,kind TEXT,auto INTEGER DEFAULT 0,active INTEGER DEFAULT 0,status TEXT,PRIMARY KEY(owner,id))");d.execSQL("CREATE TABLE items(owner TEXT,plan TEXT,tid TEXT,pos INTEGER,data TEXT,state TEXT,error TEXT,retryAt INTEGER DEFAULT 0,PRIMARY KEY(owner,plan,pos))");d.execSQL("INSERT INTO plans VALUES('123','likes','Любимое','favorites',1,0,'old')");d.execSQL("INSERT INTO plans VALUES('123','empty','Empty','own',1,0,'old')");d.execSQL("INSERT INTO items VALUES('123','likes','t1',0,'{}','READY','',0)");d.setVersion(2);d.close();try(SyncDb db=new SyncDb(c)){assertEquals(1,db.totals("123","likes")[1]);for(JSONObject p:db.plans("123",false))assertEquals(p.optString("id").equals("likes"),p.optBoolean("listed"));assertTrue(db.nextAutomaticRetry("123")>0);}}
 void signedIn()throws Exception{java.security.Provider provider=new java.security.Provider("VolnaSyntheticKeyStore",1.0,"test only"){};provider.put("KeyStore.AndroidKeyStore",WarmWriterTest.MemoryStore.class.getName());java.security.Security.insertProviderAt(provider,1);Session.put(c,"OAuth SYNTHETIC_QUEUE_TOKEN_12345","SYNTHETIC_QUEUE_CLIENT_12345");}
 void wifiNetwork(){ConnectivityManager cm=c.getSystemService(ConnectivityManager.class);Shadows.shadowOf(cm).setActiveNetworkInfo(info(ConnectivityManager.TYPE_WIFI,true));Shadows.shadowOf(cm).setNetworkCapabilities(cm.getActiveNetwork(),caps(NetworkCapabilities.TRANSPORT_WIFI));}
 @After public void cleanup(){java.security.Security.removeProvider("VolnaSyntheticKeyStore");}

 @Test public void visibleEnableQueuesQuietJobAndPreserves165Songs()throws Exception{signedIn();cached();wifiNetwork();org.robolectric.android.controller.ActivityController<android.app.Activity> controller=Robolectric.buildActivity(android.app.Activity.class).setup();android.app.Activity a=controller.get();assertTrue(AutoDownloads.toggle(a,"123","likes","Любимое","favorites"));assertNull(Shadows.shadowOf(a).getNextStartedService());SyncRequests.Request request=SyncRequests.get(c,"123","likes");assertFalse(request.token.isEmpty());assertFalse(request.refresh);assertFalse(request.force);try(SyncDb db=new SyncDb(c)){assertEquals(165,db.tracks("123","likes").size());}assertFalse(c.getSystemService(android.app.job.JobScheduler.class).getAllPendingJobs().isEmpty());controller.pause().stop().destroy();}
 @Test public void unknownListQueuesSilentRefresh()throws Exception{signedIn();plan(true);wifiNetwork();org.robolectric.android.controller.ActivityController<android.app.Activity> controller=Robolectric.buildActivity(android.app.Activity.class).setup();assertEquals(1,AutoDownloads.startVisible(controller.get()));assertNull(Shadows.shadowOf(controller.get()).getNextStartedService());assertTrue(SyncRequests.get(c,"123","likes").refresh);controller.pause().stop().destroy();}

}
